"""Complete §1 of chapter X, with independently switchable constructions and counterexamples."""
import argparse
import json

from build_grade9_vectors import BOOK, ROOT, check, make, scene

OUT = ROOT / 'geometry-course/textbook/data/vector-conclusions.json'


def source_card(number, **kwargs):
    card = make(number,kind='exercise',pages=[229],title=f'Задача {number}',**kwargs)
    card['review']={**card['review'],'reviewer':'Издание 2023 года: условие на с. 229, определение на с. 226–227, ответы №937, 939 и 940 на с. 396. В №939а буквальная запись и ответ ключа разобраны отдельно.'}
    card['answer']['prompt']={
        937:'Напиши «да» или «нет» и обоснуй вывод с помощью направления и длины.',
        938:'Запиши отдельно доказательства прямого и обратного утверждений.',
        939:'Укажи вид фигуры и объясни, какое условие позволяет сделать вывод.',
        940:'Укажи, верно ли утверждение, и приведи довод или контрпример.'
    }[number]
    return card


def trapezoid():
    # M,N,L,K go round the boundary. S,T bisect the legs MN,LK.
    points=dict(M=(0,0),N=(2,3),L=(6,3),K=(8,0),S=(1,1.5),T=(7,1.5))
    sides=[('M','N'),('N','L'),('L','K'),('K','M'),('S','T')]
    # With the bases interchanged the lengths change, while the conclusions survive.
    alternate=dict(M=(2,0),N=(0,3),L=(8,3),K=(6,0),S=(1,1.5),T=(7,1.5))
    examples=[
        ('а','NL','KL','Нет. Конец у обеих стрелок L, но начала N и K различны. Основание NL и боковая сторона KL идут по пересекающимся прямым.',
         'Наложи острия в L. Если бы совпали и направления с длинами, откуда пришлось бы начать обе стрелки?',
         'Проверь общий конец','На рисунке первая стрелка идёт по основанию к L. Вторая достигает L с боковой стороны. Для равенства недостаточно общего конца.',
         'Построй ещё один пример с узким нижним основанием. Основание и боковая сторона по-прежнему пересекаются в L под углом.',
         'Сколько различных начал у N→L и K→L?', '2','Отметь именно первые буквы N и K.',
         'У треугольника XYZ сколько из двух стрелок X→Z, Y→Z равны стрелке X→Z?', '1','Из разных вершин к Z ведут разные стрелки.'),
        ('б','MS','SN','Да. Точка S делит MN пополам, а стрелки M→S и S→N обе идут от M к N.',
         'Вторая стрелка начинается там, где заканчивается первая. Проверь, сохраняются ли направление и длина.',
         'Найди половины MN','S лежит между M и N. Обе стрелки идут вдоль одной прямой в сторону N. Равенство длин следует из того, что S — середина.',
         'Измени ширину оснований. Равенство половин MN сохраняется при любой форме трапеции.',
         'Если MN=14 см, сколько сантиметров в |S→N|?', '7','Раздели полную сторону пополам.',
         'В другом чертеже |M→S|=9 см. Какова длина MN?', '18','Вся сторона состоит из двух половин по 9.'),
        ('в','MN','KL','Нет. Боковые стороны равнобедренной трапеции равны по длине. Их прямые не параллельны, поэтому две стрелки неравны.',
         'Слово «равнобедренная» говорит о длинах ног трапеции. Проверь ещё направление.',
         'Сопоставь наклон ног','Обе стрелки могут подниматься от одного основания к другому. Первая отклоняется в одну сторону, вторая в другую. Они не сонаправлены.',
         'При перестановке широкого и узкого оснований наклоны ног меняются местами. Обе ноги по-прежнему равны по длине и не параллельны.',
         'Если боковая сторона MN длины 7 см, чему равна |K→L| в см?', '7','Длина другой ноги той же равнобедренной трапеции равна 7.',
         'На новом рисунке один вектор ведёт на 2 вправо и 3 вверх, другой на 2 влево и 3 вверх. Сколько из двух равны первому?', '1','Общее вертикальное перемещение не устраняет противоположные горизонтальные смещения.'),
        ('г','TS','KM','Нет. T→S и K→M сонаправлены. Средняя линия имеет длину полусуммы оснований и при различных основаниях отличается от каждого.',
         'Здесь обе стрелки направлены в одну сторону. Сравни среднюю линию с нижним основанием.',
         'Сравни длины параллельных стрелок','Возьми, например, NL=4 и KM=8. Тогда TS=(4+8)/2=6. Длина 6 отличается от 8. В общем случае равенство TS=KM вынудило бы NL=KM.',
         'В другом положении KM=4 и NL=8. Средняя линия снова имеет длину 6, только теперь она длиннее KM.',
         'При NL=4 и KM=8 чему равна длина T→S?', '6','Средняя линия — половина суммы 4 и 8.',
         'Если основания 6 и 12 см, какой длины будет средняя линия?', '9','Раздели 18 на 2.'),
        ('д','TL','KT','Да. K→T и T→L лежат на стороне KL, имеют одно направление и одну длину, потому что T — её середина.',
         'Прочти T→L от T к L, а затем K→T от K к T. Обе стрелки направлены к одной вершине стороны.',
         'Отследи отрезок KL','Движение K→T→L состоит из двух одинаковых половин. Порядок перечисления этих стрелок в вопросе не меняет равенства.',
         'Замени трапецию другой, сохранив T серединой KL. Длина стороны меняется, но её две половины всё ещё равны по длине и сонаправлены.',
         'Если KL=18, чему равна |K→T|?', '9','Нужна половина 18.',
         'Если на другой стороне длины 16 точка T отстоит от K на 6, чему равна длина T→L?', '10','В этом новом примере T уже не середина. Из 16 вычти 6.')]
    cards=[]
    for part,x,y,result,hint,action,explain,transfer,q1,a1,h1,q2,a2,h2 in examples:
        arrow=lambda s:s[0]+'→'+s[1]
        frames=[('Фигура и середины','MNLKST',[],sides),('Первая стрелка','MNLKST',[tuple(x)],sides),
                (action,'MNLKST',[tuple(x),tuple(y)],sides),('Поменяй основания местами','MNLKST',[tuple(x),tuple(y)],sides)]
        cases=[('Широкое основание KM','MNLKST',[tuple(x),tuple(y)],sides),('Узкое основание KM','MNLKST',[tuple(x),tuple(y)],sides)]
        cards.append(source_card(937,part=part,statement=f'В равнобедренной трапеции MNLK точки S и T делят пополам боковые стороны MN и LK. Реши, равны ли {arrow(x)} и {arrow(y)}, и обоснуй свой вывод.',
            hint=hint,result=result,stages=[('Какие точки соединяет стрелка?',f'Пройди от {x[0]} к {x[1]}. Теперь найди начало {y[0]} и конец {y[1]} другой стрелки.','У каждой ненулевой стрелки важен порядок концов.'),
                (action,explain,result),('Что будет при другой форме трапеции?',transfer,'Сравни условие о серединах, направление и длину отдельно.')],
            picture=scene([points,points,points,alternate,points,alternate],frames,cases),checks=[None,check(q1,a1,h1),check(q2,a2,h2)]))
    return cards


def common_midpoint():
    p=dict(A=(0,0),B=(3,1),C=(0,3),D=(3,4),O=(1.5,2))
    line=dict(A=(0,2),B=(2,2),C=(5,2),D=(7,2),O=(3.5,2))
    plain=[('A','D'),('B','C')];both=[('A','B'),('C','D')]
    frames=[('Две стрелки','ABCD',both,[]),('Середина отрезка BC','ABCDO',both,plain),
            ('Центральная симметрия','ABCDO',both,plain),('Все точки на прямой','ABCDO',both,plain)]
    cases=[('Наклонные отрезки','ABCDO',both,plain),('Точки на одной прямой','ABCDO',both,plain)]
    return source_card(938,statement='Докажи оба утверждения. Из равенства A→B и C→D следует совпадение середин отрезков AD и BC. Из совпадения этих середин следует равенство A→B и C→D.',
       result='Симметрия относительно общей середины меняет A и D, B и C местами. Она разворачивает направления и сохраняет расстояния. В обратную сторону достаточно взять середину BC и применить единственность равного вектора, отложенного из C.',
       hint='Возьми середину O отрезка BC и отрази точку A относительно O. Куда перейдёт B? Какая стрелка получится из C, если развернуть образ A→B?',
       stages=[('Из равных стрелок получи общую середину','Пусть A→B=C→D, а O — середина BC. Отрази A относительно O в точку X; B перейдёт в C. После разворота образа X→C стрелка C→X равна A→B. Из C можно отложить лишь один такой вектор, значит X=D и O — середина AD.','При центральной симметрии стрелка сохраняет длину и меняет направление.'),
               ('Докажи обратное утверждение','Пусть теперь середины AD и BC уже совпадают в O. Симметрия меняет A на D и B на C. При этом образ A→B — стрелка D→C, а её разворот C→D равен исходной A→B.','Построение не требует, чтобы четыре точки образовывали невырожденный параллелограмм.'),
               ('Сработает ли рассуждение на прямой?','Возьми A=0, B=2, C=5, D=7 на числовой прямой. Оба перемещения равны +2, а обе середины находятся в точке 3,5. Для нулевых стрелок A=B и C=D отрезки AD и BC совпадают.','Равенство векторов можно проверять и в вырожденных конфигурациях.')],
       picture=scene([p,p,p,line,p,line],frames,cases),
       checks=[None,check('На прямой A=0, D=8; у BC та же середина. Какова координата этой середины?', '4','Середина AD находится ровно между 0 и 8.'),
               check('На новой прямой A=1, B=4, C=6. Какую координату должен иметь D для равенства A→B=C→D?', '9','Первое перемещение равно +3. От C=6 отложи +3.')])


def quadrilaterals():
    sides=[('A','B'),('B','C'),('C','D'),('D','A')]
    counter=dict(A=(0,0),B=(5,0),C=(8,4),D=(5,8))
    rhombus=dict(A=(0,0),B=(5,0),C=(8,4),D=(3,4))
    pair=[('A','B'),('D','C')]
    frames=[('Четыре стороны','ABCD',[],sides),('Что даёт равенство длин?','ABCD',[],sides),
            ('Сравни направленные стороны','ABCD',pair,sides),('Ромб при равенстве стрелок','ABCD',pair,sides)]
    cases=[('Три равные стороны','ABCD',pair,sides),('Равные AB и DC как векторы','ABCD',pair,sides)]
    literal=source_card(939,part='а',statement='На печатной с. 229 первое равенство в №939а дано как AB=DC, без стрелок; второе сравнивает длины A→B и B→C. Выясни, что следует из записи буквально. Затем проверь, при каком уточнении получается ответ «ромб» из ключа на с. 396.',
        result='Буквальная запись даёт AB=BC=CD, но длина DA остаётся свободной. Если первое равенство относится к векторам A→B=D→C, то AB и DC параллельны и равны, ABCD — параллелограмм; при AB=BC это ромб.',
        hint='Для первой части попробуй сложить цепочку из трёх палочек одной длины, а затем соединить её концы. Для второго случая сравни сами стрелки A→B и D→C.',
        stages=[('Проверь буквальное условие','Возьми A=(0;0), B=(5;0), C=(8;4), D=(5;8). Три стороны AB, BC, CD имеют длину 5: у двух наклонных катеты 3 и 4. Но DA²=5²+8²=89, так что это не ромб. Четырёхугольник выпуклый.', 'Одинаковая длина трёх сторон сама по себе не устанавливает параллельность.'),
                ('Усиль условие до равенства векторов','Если A→B=D→C, то стороны AB и DC параллельны, равны и одинаково направлены. Значит, в четырёхугольнике одна пара противоположных сторон и параллельна, и равна. Получается параллелограмм.', 'Для этого вывода существенно сравнение направлений.'),
                ('Почему в этом случае получается ромб?','В параллелограмме BC=AD, а по условию AB=BC. Все четыре стороны равны. На втором рисунке D=(3;4): обе стрелки горизонтальны и направлены вправо, все стороны имеют длину 5.', 'Ромб — параллелограмм с равными сторонами.')],
        picture=scene([counter,counter,rhombus,rhombus,counter,rhombus],frames,cases),
        checks=[None,check('В контрпримере D=(5;8) и A=(0;0). Чему равен квадрат DA?', '89','Проверь четвёртую сторону отдельно: 5²+8²=89, а три известные стороны дают в квадрате 25.'),
                 check('На другом рисунке A→B=D→C и AB=BC=7 см. Каков периметр ABCD в см?', '28','После вывода о параллелограмме все четыре стороны равны 7.')])
    trap=dict(A=(0,0),B=(6,0),C=(4,3),D=(1,3))
    frames=[('Два условия','ABCD',[],sides),('Острия вдоль оснований','ABCD',pair,sides),
            ('Прямые боковых сторон','ABCD',[('A','D'),('B','C')],sides),('Одна пара параллельных сторон','ABCD',pair,sides)]
    second=source_card(939,part='б',statement='У четырёхугольника ABCD стрелки A→B и D→C сонаправлены. Стрелки A→D и B→C неколлинеарны. Определи вид фигуры.',
        result='ABCD — трапеция с основаниями AB и DC. Эти стороны параллельны, тогда как прямые других противоположных сторон непараллельны.',
        hint='Условие о направлении ничего не требует от длин. Подсчитай пары параллельных противоположных сторон.',
        stages=[('Переведи первое условие на язык сторон','Стрелки A→B и D→C сонаправлены, поэтому две противоположные стороны AB и DC параллельны.', 'У невырожденного четырёхугольника эти противоположные стороны лежат на разных прямых.'),
                ('Зачем дано второе условие?','A→D и B→C неколлинеарны. Значит, другую пару противоположных сторон нельзя назвать параллельной. При продолжении этих прямых они пересекутся.', 'Неколлинеарные ненулевые векторы не могут лежать на параллельных прямых.'),
                ('Как назвать четырёхугольник?','Одна пара противоположных сторон параллельна, другая нет. Это определение трапеции, в которой AB и DC являются основаниями.', 'Для вывода не требуется равенство длин оснований.')],
        picture=scene(trap,frames),checks=[None,check('Сколько пар противоположных сторон здесь параллельно?', '1','Из двух пар только AB и DC удовлетворяют этому условию.'),
                 check('Если вместо второго условия известно A→D и B→C коллинеарны, сколько пар параллельных противоположных сторон будет у нового невырожденного четырёхугольника?', '2','Первая пара осталась параллельной, добавилась вторая.')])
    return [literal,second]


def true_or_false():
    p=dict(A=(0,0),B=(3,0),C=(1,2),D=(4,2))
    collinear={**p,'C':(4,0),'D':(7,0)}
    back={**p,'C':(4,2),'D':(1,2)}
    long={**p,'D':(6,2)}
    zero=dict(M=(0,0),C=(1,2),D=(4,2))
    double_zero={**zero,'N':(3,2)}
    arrows=[('A','B'),('C','D')]
    questions=[
        ('а','Если векторы a и b равны, обязаны ли они быть сонаправленными?',
         'Да. Сонаправленность входит в определение равных векторов. Для нулевого вектора действует соглашение, принятое в книге.',
         'Сформулируй определение равенства, начиная со слова «сонаправлены».',
         [('Найди две равные стрелки','На чертеже a=A→B и b=C→D. Обе стрелки ведут на три единицы вправо. Расположение на разных строках не мешает равенству.'),
          ('Применяй определение','Если a=b, уже известны и совпадающие направления, и равные длины. Поэтому из равенства следует сонаправленность.'),
          ('Измени расположение','Перенеси b на ту же прямую, на которой лежит a, оставив направление и длину. Вывод остаётся тем же.')],
         [p,p,p,collinear],['ABCD']*4,[arrows,[arrows[0]],arrows,arrows],
         ('Из двух равных ненулевых стрелок сколько сонаправлены первой?', '2','Первая стрелка сонаправлена себе, вторая — ей по равенству.'),
         ('Из трёх копий одной ненулевой стрелки две развернули. Сколько сохранили её направление?', '1','После разворота две стрелки смотрят обратно.')),
        ('б','Обязательно ли равные векторы a и b коллинеарны?',
         'Да. Равные ненулевые векторы сонаправлены, следовательно, лежат на одной или на параллельных прямых. Нулевой вектор тоже коллинеарен любому.',
         'Проведи несущие прямые вдоль двух стрелок. Могут ли они пересекаться под углом, если стрелки равны?',
         [('Сравни прямые','У двух одинаковых стрелок на разных строках прямые параллельны.'),
          ('Учти второй случай','Если стрелки расположены на одной прямой, они тоже коллинеарны. Для коллинеарности не нужно проверять, совпадают ли начальные точки.'),
          ('Проверь крайний случай','Ни у двух равных ненулевых векторов, ни у двух нулевых равенство не нарушает коллинеарность.')],
         [p,p,collinear,p],['ABCD']*4,[arrows,arrows,arrows,arrows],
         ('Сколько различных несущих прямых нужно для двух равных горизонтальных стрелок в разных строках?', '2','Две разные строки дают две параллельные прямые.'),
         ('На новом рисунке обе ненулевые равные стрелки лежат на одной оси. Сколько теперь различных несущих прямых?', '1','Обе стрелки принадлежат одной и той же оси.')),
        ('в','Правда ли, что равные векторы обязательно противоположно направлены?',
         'Нет. Например, две ненулевые стрелки по три единицы вправо равны и сонаправлены. Один контрпример опровергает утверждение «обязательно».',
         'Возьми одну ненулевую стрелку и перенеси её на соседнюю строку без поворота.',
         [('Построй контрпример','Возьми a и b по три единицы вправо. Предпосылка a=b выполнена, а острия указывают одно и то же направление.'),
          ('Попробуй развернуть b','После разворота b действительно смотрит против a. Полученные векторы уже не равны. Одновременно исходное условие и предложенный вывод здесь не выполнены.'),
          ('Объясни, почему примера достаточно','Верни b в исходное положение. Для опровержения слова «всегда» достаточно одной подходящей пары равных стрелок, у которых противоположного направления нет.')],
         [p,p,back,p],['ABCD']*4,[arrows,arrows,arrows,arrows],
         ('Сколько из двух равных ненулевых стрелок вправо направлены влево?', '0','Перенос без поворота сохраняет острие справа.'),
         ('Три равные стрелки направлены вверх. Одну развернули. Сколько теперь направлены противоположно первоначальной?', '1','Только развёрнутая стрелка смотрит вниз.')),
        ('г','Следует ли из сонаправленности a и b, что эти векторы равны?',
         'Нет. Стрелки длиной 3 и 5 единиц вправо сонаправлены, но имеют разные длины. Для равенства нужно ещё равенство модулей.',
         'Построй короткую стрелку вправо и более длинную стрелку в том же направлении.',
         [('Задай условие','Пусть обе стрелки направлены вправо. Это уже обеспечивает их сонаправленность.'),
          ('Проверь длины','У образца a длина 3, у b длина 5. Острия смотрят вправо, но концы не совпадут, если совместить начала. Равенства нет.'),
          ('Исправь недостающее условие','Укороти b до длины 3, не поворачивая. Теперь векторы равны. Значит, равенство иногда возможно, но не следует из одной сонаправленности.')],
         [long,long,long,p],['ABCD']*4,[arrows,[arrows[0]],arrows,arrows],
         ('На сколько единиц длина 5 отличается от длины 3?', '2','Вычти длину короткой стрелки из длины длинной.'),
         ('Из четырёх сонаправленных стрелок длины 4, 6, 4 и 8 сколько равны вектору длины 4 того же направления?', '2','Оставь только стрелки длины 4.')),
        ('д','Если a — нулевой вектор, сонаправлен ли он с произвольным вектором b?',
         'Да, по соглашению этого учебника (п. 85, с. 227). Нулевому вектору не приписывают определённое направление, поэтому его считают сонаправленным с любым вектором.',
         'Вспомни отдельное соглашение о нулевом векторе. У точки, изображающей его, нет острия.',
         [('Покажи нулевое перемещение','Вектор a=M→M обозначен точкой M: его начало и конец совпадают, длина равна нулю. Рисовать к нему стрелу вправо или вверх не нужно.'),
          ('Проверь произвольный b','Стрелка b=C→D может быть любой. По соглашению a сонаправлен с ней независимо от положения C и D. Это утверждение не делает ненулевой b равным a.'),
          ('А если и b нулевой?','Пусть b=N→N. Теперь на рисунке две точки без стрелок. Оба вектора нулевые, равны и по тому же соглашению сонаправлены.')],
         [zero,zero,zero,double_zero],['MCD','M','MCD','MN'],[[('C','D')],[],[('C','D')],[]],
         ('Какова длина нулевого вектора M→M?', '0','Начало и конец совпали.'),
         ('Среди векторов длины 2, 0 и 5 сколько сонаправлены с нулевым по соглашению книги?', '3','Соглашение относится к каждому вектору, в том числе к нулевому.'))]
    reasons={
        'а':['Параллельный перенос сохраняет направление и длину стрелки.','Сонаправленность — необходимая часть определения равных векторов.'],
        'б':['На параллельных прямых ненулевые стрелки коллинеарны.','Коллинеарность допускает и расположение на одной прямой.'],
        'в':['Контрпример обязан удовлетворять исходному условию.','Разворот ненулевого вектора нарушает равенство с исходным.'],
        'г':['Длину можно менять, сохраняя направление.','Равные векторы имеют равные длины.'],
        'д':['Нулевой вектор имеет совпадающие начало и конец.','Сонаправленность с нулевым вектором оговорена отдельно в определении.']
    }
    cards=[]
    for part,question,result,hint,steps,positions,visible,arrows_per_frame,original,repeat in questions:
        labels=['Условие']+[title for title,_ in steps]
        picture=scene(positions,[(label,v,a,[]) for label,v,a in zip(labels,visible,arrows_per_frame,strict=True)])
        if part=='д':picture['description']='Точкой без острия изображён нулевой вектор; ненулевой вектор изображён стрелкой.'
        cards.append(source_card(940,part=part,statement=question+' Объясни решение на основании определения или подбери контрпример.',
                     hint=hint,result=result,stages=[(title,text,result if i==2 else reasons[part][i]) for i,(title,text) in enumerate(steps)],
                     picture=picture,checks=[None,check(*original),check(*repeat)]))
    return cards


def build():
    return dict(bookId=BOOK,lessons=trapezoid()+[common_midpoint()]+quadrilaterals()+true_or_false())


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    serialized=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if args.check:assert OUT.read_text()==serialized
    else:OUT.write_text(serialized)
